// Campos que você quer normalizar (adicione/remova aqui)
const phoneFields = ['TELCELENT']; // ex: ['TELCOB','TELRES','TELCEL']

function normalizeBRPhone(value) {
  if (value === null || value === undefined) return null;

  // só dígitos
  let d = String(value).replace(/\D+/g, '');

  // remove prefixos comuns
  // 0 + DDD... (ex.: 085...) -> remove o 0
  if (d.length >= 11 && d.startsWith('0')) d = d.replace(/^0+/, '');

  // se vier com 55 na frente
  if (d.startsWith('55')) d = d.slice(2);

  // agora esperamos: DDD(2) + número(8 ou 9)
  if (d.length === 10) {
    // DDD + 8 dígitos -> insere o 9 após o DDD
    d = d.slice(0, 2) + '9' + d.slice(2);
  } else if (d.length === 11) {
    // ok (DDD + 9)
  } else {
    // inválido / inesperado
    return null;
  }

  // retorna no formato pedido: 55XX999999999
  return '55' + d;
}

// --- aplica nos campos ---
for (const f of phoneFields) {
  if (f in $json) {
    $json[f] = normalizeBRPhone($json[f]);
  }
}

return $json;

